"""Frozen original safety facts and current protection epoch."""
# ruff: noqa: E501

TABLES = ('original_scan_requests', 'original_scan_results', 'original_security')

SCHEMA_SQL = ("\nCREATE TABLE original_scan_requests (\n\tproduct_id UUID NOT NULL, \n\toriginal_id UUID NOT NULL, \n\trequester_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tbinding JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, original_id, id), \n\tUNIQUE (tenant_id, product_id, original_id, revision), \n\tFOREIGN KEY(tenant_id, product_id, original_id) REFERENCES uploaded_originals (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, requester_id) REFERENCES principals (tenant_id, id), \n\tCHECK (revision > 0 AND status = 'requested')\n)\n\n", 'CREATE INDEX ix_original_scan_requests_tenant_id ON original_scan_requests (tenant_id)', "\nCREATE TABLE original_scan_results (\n\tproduct_id UUID NOT NULL, \n\toriginal_id UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tresult JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, request_id), \n\tFOREIGN KEY(tenant_id, product_id, original_id, request_id) REFERENCES original_scan_requests (tenant_id, product_id, original_id, id), \n\tCHECK (revision > 0 AND status IN ('clean','infected','unknown','unavailable','timeout','rejected'))\n)\n\n", 'CREATE INDEX ix_original_scan_results_tenant_id ON original_scan_results (tenant_id)', "\nCREATE TABLE original_security (\n\tproduct_id UUID NOT NULL, \n\toriginal_id UUID NOT NULL, \n\tepoch INTEGER NOT NULL, \n\tsource_state VARCHAR(16) NOT NULL, \n\tdisposition VARCHAR(16) NOT NULL, \n\tcurrent_request_id UUID, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, original_id), \n\tFOREIGN KEY(tenant_id, product_id, original_id) REFERENCES uploaded_originals (tenant_id, product_id, id), \n\tFOREIGN KEY(tenant_id, product_id, original_id, current_request_id) REFERENCES original_scan_requests (tenant_id, product_id, original_id, id), \n\tCHECK (epoch > 0 AND source_state IN ('active','withdrawn')), \n\tCHECK (disposition IN ('active','quarantined','unknown'))\n)\n\n", 'CREATE INDEX ix_original_security_tenant_id ON original_security (tenant_id)')
